int main(void){struct environment e;CHECK(open(&e,detailed,reference,1)==0&&built(&e)==0);e.old=e.input;e.input=NULL;(void)ube_gc_collect();uint64_t hash=owners_hash(e.old);CHECK(hash!=0);CHECK(remake(&e,2,1)==0);struct failure f={.kind=5,.code=1428};begin(0);CHECK(catalog_build(e.input,&f)&&f.kind==0);end();size_t need=observed.roots_peak-observed.roots_before;CHECK(need>0&&need<=512);e.input=NULL;(void)ube_gc_collect();size_t old_bytes=ube_gc_live_allocation_bytes();CHECK(remake(&e,2,1)==0);size_t before=index_root_count(),capacity=index_root_limit()-before;root* backed=calloc(capacity,sizeof *backed);void** slots=calloc(capacity,sizeof *slots);CHECK(backed&&slots&&capacity>4096);for(size_t i=0;i<capacity;++i)CHECK(ube_gc_root_enter(&backed[i],&slots[i]));for(size_t available=0;available<=need+1;++available){if(available){for(size_t i=capacity-4096;i<capacity-(available-1);++i)CHECK(ube_gc_root_leave(&backed[i]));e.input=NULL;(void)ube_gc_collect();CHECK(ube_gc_live_allocation_bytes()==old_bytes&&owners_hash(e.old)==hash);CHECK(remake(&e,2,1)==0);for(size_t i=capacity-4096;i<capacity-available;++i)CHECK(ube_gc_root_enter(&backed[i],&slots[i]));}CHECK(index_root_count()==index_root_limit()-available);f=(struct failure){.kind=5,.code=1428};int ok=catalog_build(e.input,&f);if(ok!=(available>=need)||(ok?f.kind!=0:f.kind!=5||f.code!=1428))fprintf(stderr,"catalog root capacity=%zu need=%zu ok=%d kind=%d code=%d\n",available,need,ok,f.kind,f.code);CHECK(ok==(available>=need)&&(ok?f.kind==0:f.kind==5&&f.code==1428)&&index_root_count()==index_root_limit()-available&&owners_hash(e.old)==hash);}for(size_t i=0;i<capacity-need-1;++i)CHECK(ube_gc_root_leave(&backed[i]));free(backed);free(slots);CHECK(close_env(&e)==0);printf("PASS catalog root assertions:%u rootNeed:%zu capacities:%zu realBacked:1\n",assertions,need,need+2);return 0;}
